    protected Set fieldIdsToHash()
    {
        Set ret = next fieldIdsToHash();    // See MarkupAutoTableGUP_Extension

        // MPJ-26540 - Workaround, possible bug in pricing engine related to search of auto.charges. Skip addition
        // of Description in hashing function as it doesn't seem to be set correctly when attempting to find matching auto
        // charges.
        return new Set(Types::Integer);
    }
